package br.gov.ma.pacodolumiar.semed.tecnico;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.location.*;import android.os.*;import java.util.concurrent.*;import org.json.JSONObject;
public class LocationService extends Service implements LocationListener {
 private volatile Location last;private String id,csrf;private ScheduledExecutorService executor;private volatile long lastConfirmed;private volatile boolean ended=false;
 @Override public IBinder onBind(Intent i){return null;}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent==null){stopSelf();return START_NOT_STICKY;}String next=intent.getStringExtra("attendance");if(next!=null&&next.equals(id))return START_NOT_STICKY;id=next;csrf=intent.getStringExtra("csrf");if(id==null||csrf==null){stopSelf();return START_NOT_STICKY;}
  NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("location","Localização durante atendimento",NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);
  Notification n=new Notification.Builder(this,"location").setSmallIcon(android.R.drawable.ic_menu_mylocation).setContentTitle("SEMED · atendimento em andamento").setContentText("Compartilhando localização. Abra para concluir ou interromper.").setContentIntent(open).setOngoing(true).setOnlyAlertOnce(true).build();
  try{if(Build.VERSION.SDK_INT>=29)startForeground(105,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_LOCATION);else startForeground(105,n);LocationManager lm=(LocationManager)getSystemService(LOCATION_SERVICE);for(String p:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER})if(lm.isProviderEnabled(p))lm.requestLocationUpdates(p,15000,10,this,Looper.getMainLooper());}catch(Exception e){stopSelf();return START_NOT_STICKY;}
  if(executor!=null)executor.shutdownNow();lastConfirmed=System.currentTimeMillis();executor=Executors.newSingleThreadScheduledExecutor();executor.scheduleWithFixedDelay(this::send,0,25,TimeUnit.SECONDS);return START_NOT_STICKY;
 }
 private void send(){if(ended)return;try{JSONObject a=Api.call("/api/technician/active",null,null);int code=a.optInt("_http");if(code==401||code==403||code==200&&(a.isNull("attendance")||!id.equals(a.getJSONObject("attendance").optString("id")))){stopSelf();return;}if(code!=200)throw new Exception();lastConfirmed=System.currentTimeMillis();Location l=last;if(l==null||System.currentTimeMillis()-l.getTime()>90000)return;JSONObject p=new JSONObject().put("latitude",l.getLatitude()).put("longitude",l.getLongitude()).put("accuracy",l.getAccuracy()).put("observedAt",l.getTime());JSONObject r=Api.call("/api/technician/position",new JSONObject().put("attendanceId",id).put("position",p),csrf);if(r.optInt("_http")==409||r.optInt("_http")==401||r.optInt("_http")==403)stopSelf();}catch(Exception e){if(System.currentTimeMillis()-lastConfirmed>180000)stopSelf();}}
 public void onLocationChanged(Location l){last=l;}public void onStatusChanged(String p,int s,Bundle b){}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}
 @Override public void onDestroy(){ended=true;if(executor!=null)executor.shutdownNow();((LocationManager)getSystemService(LOCATION_SERVICE)).removeUpdates(this);last=null;id=null;csrf=null;stopForeground(true);super.onDestroy();}
}
